const normalizedEnglish = new Map(
  Object.entries(english).map(([indonesian, translated]) => [normalize(indonesian), translated]),
);
const normalizedIndonesian = new Map(
  Object.entries(english).map(([indonesian, translated]) => [normalize(translated), indonesian]),
);

function normalize(value: string): string {
  return value.replace(/\s+/g, " ").trim().toLocaleLowerCase("id-ID");
}

export function translatePhrase(value: string, language: SiteLanguage): string {
  const dictionary = language === "en" ? normalizedEnglish : normalizedIndonesian;
  const exactTranslation = dictionary.get(normalize(value));
  if (exactTranslation) return exactTranslation;

  const monthNames = language === "en"
    ? { januari: "January", februari: "February", maret: "March", april: "April", mei: "May", juni: "June", juli: "July", agustus: "August", september: "September", oktober: "October", november: "November", desember: "December" }
    : { january: "Januari", february: "Februari", march: "Maret", april: "April", may: "Mei", june: "Juni", july: "Juli", august: "Agustus", september: "September", october: "Oktober", november: "November", december: "Desember" };
  const translatedDate = value.replace(/\b(januari|februari|maret|april|mei|juni|juli|agustus|september|oktober|november|desember|january|february|march|may|june|july|august|october|december)\b/gi, (month) => {
    return monthNames[month.toLocaleLowerCase("id-ID") as keyof typeof monthNames] ?? month;
  });
  if (translatedDate !== value) return translatedDate;

  // Preserve server-provided detail while translating known Indonesian labels
  // such as "Agenda belum dapat dimuat: ..." without an external API.
  if (language === "en") {
    const separator = value.indexOf(": ");
    if (separator > 0) {
      const label = value.slice(0, separator);
      const translatedLabel = normalizedEnglish.get(normalize(label));
      if (translatedLabel) return `${translatedLabel}: ${value.slice(separator + 2)}`;
    }
  }

  return value;
}
